// Mapeo de meses en español a número
const meses = {
  'enero': 0, 'febrero': 1, 'marzo': 2, 'abril': 3,
  'mayo': 4, 'junio': 5, 'julio': 6, 'agosto': 7,
  'septiembre': 8, 'octubre': 9, 'noviembre': 10, 'diciembre': 11
};

// Obtenemos el mes y año actual
const ahora = new Date();
const mesActual = ahora.getMonth() - 1;
const anioActual = ahora.getFullYear();

// Array para guardar los resultados filtrados
const resultadosFiltrados = [];

// Iteramos sobre cada item (fila) que llega al nodo
for (const item of $input.all()) {
  // Extraemos la fecha del JSON
  const fechaString = item.json.Fecha;

  // "18 de agosto de 2025 13:28" -> ["18", "agosto", "2025", "13:28"]
  const partes = fechaString.replace(' de ', ' ').replace(' de ', ' ').split(' ');
  const dia = parseInt(partes[0]);
  const mes = meses[partes[1].toLowerCase()];
  const anio = parseInt(partes[2]);

  // Si el mes y el año de la fila coinciden con el actual, lo guardamos
  if (mes === mesActual && anio === anioActual) {
    resultadosFiltrados.push(item);
  }
}

// Devolvemos solo los items que cumplen la condición
return resultadosFiltrados;

const items = $input.all();

if (items.length === 0) {
  return [{ json: { html: "<p>No hay interacciones para reportar este mes.</p>" } }];
}

let tablaHtml = `
  <h1>Reporte de Interacciones del Mes</h1>
  <p>Total de interacciones: ${items.length}</p>
  <table border="1" style="width:100%; border-collapse: collapse;">
    <thead>
      <tr>
        <th style="padding: 8px; background-color: #f2f2f2;">Fecha</th>
        <th style="padding: 8px; background-color: #f2f2f2;">Hora</th> <th style="padding: 8px; background-color: #f2f2f2;">Nombre</th>
        <th style="padding: 8px; background-color: #f2f2f2;">Solicitud</th>
      </tr>
    </thead>
    <tbody>
`;

for (const item of items) {
  // Asegúrate que los nombres de las propiedades (item.json.Fecha, item.json.Hora, etc.)
  // coincidan EXACTAMENTE con los encabezados de tu Google Sheet.
  tablaHtml += `
    <tr>
      <td style="padding: 8px;">${item.json.Fecha}</td>
      <td style="padding: 8px;">${item.json.Hora || ''}</td> <td style="padding: 8px;">${item.json.Nombre}</td>
      <td style="padding: 8px;">${item.json.Solicitud}</td>
    </tr>
  `;
}

tablaHtml += `
    </tbody>
  </table>
`;

return [{ json: { html: tablaHtml } }];
